import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Module-level font loading for Lambda safety
const { fontFamily: spaceFont } = loadSpaceGrotesk();
const { fontFamily: interFont } = loadInter();



export type MarginDataFeedProps = Record<string, any>;

const MarginDataFeed: React.FC<MarginDataFeedProps> = ({
  backgroundColor = "#090004",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryPink = "#FF1493",
  secondaryPink = "#FF69B4",
  trackColor = "#33001a",
  projects = [
    { name: "Product 1", margin: 42.5 },
    { name: "Product 2", margin: 68.2 },
    { name: "Product 3", margin: 85.0 },
    { name: "Product 4", margin: 54.7 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Layout Calculations (Centered to fit in-frame for portrait & landscape)
  const boxWidth = 380;
  const platformBoxWidth = 380;
  const gap = 200; // Space between projects and platforms
  
  const totalContentWidth = boxWidth + gap + platformBoxWidth;
  const leftX = (width - totalContentWidth) / 2;
  const rightX = leftX + boxWidth + gap;

  const projectBoxHeight = 130;
  const platformBoxHeight = 280;

  // Project Positions
  const projectSpacing = 40;
  const totalProjectsHeight =
    projects.length * projectBoxHeight + (projects.length - 1) * projectSpacing;
  const projectsStartY = (height - totalProjectsHeight) / 2;

  // Platform Positions
  const platformSpacing = 100;
  const platformsTotalHeight = platformBoxHeight * 2 + platformSpacing;
  const platformsStartY = (height - platformsTotalHeight) / 2;
  const googleStartY = platformsStartY;
  const metaStartY = platformsStartY + platformBoxHeight + platformSpacing;

  // SVG Curve Generator
  const createCurve = (sx: number, sy: number, ex: number, ey: number) => {
    const cp1x = sx + (ex - sx) * 0.5;
    const cp1y = sy;
    const cp2x = ex - (ex - sx) * 0.5;
    const cp2y = ey;
    return `M ${sx} ${sy} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${ex} ${ey}`;
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFont }}>
      {/* Background SVG for Paths and Effects */}
      <svg
        style={{ position: "absolute", top: 0, left: 0, width, height }}
        viewBox={`0 0 ${width} ${height}`}
      >
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="6" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* Render Connection Lines */}
        {projects.map((_, i) => {
          const startX = leftX + boxWidth;
          const startY = projectsStartY + i * (projectBoxHeight + projectSpacing) + projectBoxHeight / 2;

          const toGoogleY = googleStartY + platformBoxHeight / 2 + (i * 20 - projects.length * 10);
          const toMetaY = metaStartY + platformBoxHeight / 2 + (i * 20 - projects.length * 10);

          const googlePath = createCurve(startX, startY, rightX, toGoogleY);
          const metaPath = createCurve(startX, startY, rightX, toMetaY);

          const lineDrawStart = 40 + i * 5;
          const lineDrawProgress = spring({
            frame: frame - lineDrawStart,
            fps,
            config: { damping: 14, stiffness: 60 },
          });

          const pathLength = 1200; // Approximate path length
          const offset = interpolate(lineDrawProgress, [0, 1], [pathLength, 0], {
            extrapolateRight: "clamp",
          });

          // Data feed offset starts after the line is drawn
          const feedOffset = frame - lineDrawStart > 20 ? -(frame - (lineDrawStart + 20)) * 8 : 0;
          const feedOpacity = interpolate(frame - (lineDrawStart + 20), [0, 10], [0, 1], {
            extrapolateRight: "clamp",
            extrapolateLeft: "clamp",
          });

          return (
            <g key={`path-group-${i}`}>
              {/* Google Connection Tracks */}
              <path
                d={googlePath}
                fill="none"
                stroke={trackColor}
                strokeWidth={3}
                strokeDasharray={pathLength}
                strokeDashoffset={offset}
              />
              <path
                d={googlePath}
                fill="none"
                stroke={secondaryPink}
                strokeWidth={4}
                strokeDasharray="12 40"
                strokeDashoffset={feedOffset}
                opacity={feedOpacity}
                filter="url(#glow)"
              />

              {/* Meta Connection Tracks */}
              <path
                d={metaPath}
                fill="none"
                stroke={trackColor}
                strokeWidth={3}
                strokeDasharray={pathLength}
                strokeDashoffset={offset}
              />
              <path
                d={metaPath}
                fill="none"
                stroke={primaryPink}
                strokeWidth={4}
                strokeDasharray="12 40"
                strokeDashoffset={feedOffset}
                opacity={feedOpacity}
                filter="url(#glow)"
              />
            </g>
          );
        })}
      </svg>

      {/* Project Nodes (Left Side) */}
      {projects.map((project, i) => {
        const enterStart = 10 + i * 8;
        const enterProgress = spring({
          frame: frame - enterStart,
          fps,
          config: { damping: 12, stiffness: 80 },
        });

        const yPos = projectsStartY + i * (projectBoxHeight + projectSpacing);
        const currentMargin = interpolate(frame, [enterStart + 15, enterStart + 45], [0, project.margin], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: leftX,
              top: yPos,
              width: boxWidth,
              height: projectBoxHeight,
              backgroundColor: "#110008",
              border: `1px solid ${trackColor}`,
              borderRadius: 16,
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "0 30px",
              boxShadow: `0 0 20px ${primaryPink}10`,
              transform: `translateX(${interpolate(enterProgress, [0, 1], [-100, 0])}px) scale(${enterProgress})`,
              opacity: enterProgress,
            }}
          >
            <div style={{ color: "#FFFFFF", fontSize: 28, fontWeight: 600 }}>
              {project.name}
            </div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
              <div
                style={{
                  color: secondaryPink,
                  fontSize: 14,
                  fontWeight: 600,
                  textTransform: "uppercase",
                  letterSpacing: 2,
                  marginBottom: 4,
                }}
              >
                Margin
              </div>
              <div
                style={{
                  color: primaryPink,
                  fontSize: 38,
                  fontFamily: spaceFont,
                  fontWeight: 700,
                }}
              >
                {currentMargin.toFixed(1)}%
              </div>
            </div>
          </div>
        );
      })}

      {/* Platforms (Right Side) */}
      {[
        { name: "Google", y: googleStartY, color: secondaryPink, icon: <GoogleIcon /> },
        { name: "Meta", y: metaStartY, color: primaryPink, icon: <MetaIcon /> },
      ].map((platform, i) => {
        const enterStart = 25 + i * 15;
        const enterProgress = spring({
          frame: frame - enterStart,
          fps,
          config: { damping: 14, stiffness: 70 },
        });

        // Pulse effect based on incoming data
        const isReceivingData = frame > 60;
        const pulse = isReceivingData ? (Math.sin((frame - 60) * 0.2) + 1) / 2 : 0;
        const boxShadowOp = interpolate(pulse, [0, 1], [0.1, 0.4]);
        const borderGlow = interpolate(pulse, [0, 1], [0.3, 1]);

        return (
          <div
            key={platform.name}
            style={{
              position: "absolute",
              left: rightX,
              top: platform.y,
              width: platformBoxWidth,
              height: platformBoxHeight,
              backgroundColor: "#110008",
              border: `2px solid rgba(${platform.name === "Meta" ? "255, 20, 147" : "255, 105, 180"}, ${borderGlow})`,
              borderRadius: 24,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: `0 0 40px ${platform.color}${Math.floor(boxShadowOp * 255).toString(16).padStart(2, "0")}`,
              transform: `translateX(${interpolate(enterProgress, [0, 1], [100, 0])}px) scale(${enterProgress})`,
              opacity: enterProgress,
            }}
          >
            <div
              style={{
                width: 90,
                height: 90,
                color: platform.color,
                marginBottom: 20,
              }}
            >
              {platform.icon}
            </div>
            <div
              style={{
                color: "#FFFFFF",
                fontSize: 48,
                fontFamily: spaceFont,
                fontWeight: 700,
                letterSpacing: 1,
              }}
            >
              {platform.name}
            </div>
            <div
              style={{
                color: platform.color,
                fontSize: 20,
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: 4,
                marginTop: 10,
                opacity: 0.8,
              }}
            >
              Data Intake
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// --- Inline Icons to avoid external asset dependency ---

const GoogleIcon = () => (
  <svg viewBox="0 0 24 24" fill="currentColor">
    <path d="M12.545,10.239v3.821h5.445c-0.712,2.315-2.647,3.972-5.445,3.972c-3.332,0-6.033-2.701-6.033-6.032s2.701-6.032,6.033-6.032c1.498,0,2.866,0.549,3.921,1.453l2.814-2.814C17.503,2.988,15.139,2,12.545,2C7.021,2,2.543,6.477,2.543,12s4.478,10,10.002,10c8.396,0,10.249-7.85,9.426-11.748L12.545,10.239z" />
  </svg>
);

const MetaIcon = () => (
  <svg viewBox="0 0 24 24" fill="currentColor">
    <path d="M17.5 5.5h-2.1c-1.8 0-3.3.9-4.2 2.3l-2.4 3.7c-.5.7-1.3 1.1-2.1 1.1H4.5c-1.1 0-2-.9-2-2s.9-2 2-2h2.2c.5 0 1-.3 1.3-.7l1.1-1.7c-1-1.1-2.4-1.8-4-1.8-3 0-5.5 2.5-5.5 5.5S2 15.5 5 15.5h2.1c1.8 0 3.3-.9 4.2-2.3l2.4-3.7c.5-.7 1.3-1.1 2.1-1.1h2.2c1.1 0 2 .9 2 2s-.9 2-2 2h-2.2c-.5 0-1 .3-1.3.7l-1.1 1.7c1 1.1 2.4 1.8 4 1.8 3 0 5.5-2.5 5.5-5.5s-2.5-5.5-5.5-5.5z" />
  </svg>
);

export default MarginDataFeed;